-- Seed the simple applicant-facing job-type catalogue from the owner's audited workbook.
-- This creates occupation/job-type records only. It MUST NOT create vacancy rows.
-- All imported records start pending and inactive; no official classification is claimed.
-- Generated setting/seniority variants from the 5,000-row workbook are intentionally not imported.
-- The existing 25 public.job_categories rows remain the category source of truth.

BEGIN;

DO $preflight$
BEGIN
  IF to_regclass('public.occupations') IS NULL THEN
    RAISE EXCEPTION 'Required public.occupations table is missing; apply the reviewed workflow schema first.';
  END IF;
  IF to_regclass('public.job_categories') IS NULL THEN
    RAISE EXCEPTION 'Required existing public.job_categories table is missing; refusing to create a replacement.';
  END IF;
  IF (SELECT count(*) FROM public.job_categories WHERE is_active = true) <> 25 THEN
    RAISE EXCEPTION 'Expected the 25 existing active Job Grid categories; refusing to seed an incomplete or changed category list.';
  END IF;
  IF EXISTS (
    SELECT expected.slug
    FROM (VALUES
      ('agriculture-farming'),
      ('construction-building'),
      ('skilled-trades-repair'),
      ('driving-transport'),
      ('warehouse-logistics'),
      ('cleaning-housekeeping'),
      ('security-safety'),
      ('hospitality-tourism'),
      ('food-service-catering'),
      ('retail-sales'),
      ('customer-service'),
      ('general-labour'),
      ('manufacturing-factory'),
      ('domestic-household-work'),
      ('health-care-caregiving'),
      ('education-training'),
      ('office-administration'),
      ('it-technology'),
      ('finance-accounting'),
      ('engineering'),
      ('beauty-personal-care'),
      ('maintenance-facilities'),
      ('marketing-communications'),
      ('professional-services'),
      ('other')
    ) AS expected(slug)
    LEFT JOIN public.job_categories AS actual
      ON actual.slug = expected.slug AND actual.is_active = true
    WHERE actual.slug IS NULL
  ) THEN
    RAISE EXCEPTION 'At least one workbook category slug is missing or inactive in public.job_categories.';
  END IF;
END;
$preflight$;

INSERT INTO public.occupations (
  category_slug,
  canonical_title,
  verification_status,
  verification_notes,
  is_active
)
