    ) AS seed(canonical_title, category_slug)
    JOIN public.occupations AS occupation
      ON occupation.normalized_title =
         lower(regexp_replace(btrim(seed.canonical_title), '[[:space:]]+', ' ', 'g'))
     AND occupation.category_slug = seed.category_slug
  ) <> 496 THEN
    RAISE EXCEPTION 'Job-type seed verification failed: expected all 496 unique base titles in their intended categories.';
  END IF;
END;
$validation$;

COMMIT;
